        TEXTS.put(AppearanceVariant.APPEARANCEBOB, new String[] {"Bob", "Who's a good Bob?", "Prrr...", "You scratch Bob behind the ears. They purr like a tiny dragon.", "Go on, Bob!", "Mrrrow?", "Bob pads away, quite certain you will miss them.", "Here you go, Bob!", "Fish, perhaps?", "Bob bats the bones with a paw. They were hoping for fish.", "Here you go, Bob!", "Prrr...", "Bob tucks into the meat, then gives their whiskers a proud little wash.", "Bob sniffs the offering, then politely looks elsewhere."});
        TEXTS.put(AppearanceVariant.APPEARANCEEVILBOB, new String[] {"Evil Bob", "Who's a good Evil Bob?", "I allow this.", "Evil Bob accepts your scritches as a tribute to their fluffy magnificence.", "Go on, Evil Bob!", "You go on!", "Evil Bob stalks away, pretending the idea was theirs.", "Here you go, Evil Bob!", "Uncook them!", "Evil Bob examines the bones. Apparently your tribute is far too cooked.", "Here you go, Evil Bob!", "Raw tribute!", "Evil Bob claims the meat with a smug little purr.", "Evil Bob rejects the offering with a very small, very imperial huff."});
        TEXTS.put(AppearanceVariant.APPEARANCEWISEOLDMAN, new String[] {"Wise Old Man", "Who's a good old man?", "Ahem.", "You give the Wise Old Man a friendly pat. He clears his throat.", "Go on, Wise Old Man!", "How rude!", "The Wise Old Man walks away, muttering about manners.", "Here you go, Wise Old Man!", "Not a banknote.", "The Wise Old Man inspects the bones. He seems unimpressed.", "Here you go, Wise Old Man!", "Not a banknote.", "The Wise Old Man inspects the meat. He would rather have a proper meal.", "Wise Old Man shows no interest in that item."});
        TEXTS.put(AppearanceVariant.APPEARANCEITEMCABBAGE, new String[] {"Cabbage", "Who's a good cabbage?", "Kah-Bah-Gee!", "You pat the cabbage. Its leaves rustle: Kah-Bah-Gee!", "Go on, Cabbage!", "Leaf me be!", "The cabbage rolls away with an indignant rustle.", "Here you go, Cabbage!", "For the patch!", "You hear a faint, leafy crunch as the bone dissolves into fertilizer.", "Here you go, Cabbage!", "For the patch!", "The meat settles among its leaves and crumbles into compost.", "The cabbage rustles, unimpressed by your offering."});
        TEXTS.put(AppearanceVariant.APPEARANCEGIANTCABBAGE, new String[] {"Giant cabbage", "Who's a good cabbage?", "KAH-BAH-GEE!", "You pat the giant cabbage. Its leaves rustle: KAH-BAH-GEE!", "Go on, Giant cabbage!", "KAH-BAH-BEGONE!", "The giant cabbage rolls away with an indignant rustle.", "Here you go, Giant cabbage!", "ALL HAIL THE PATCH!", "The bones vanish into the folds, followed by a wet, echoing crunch.", "Here you go, Giant cabbage!", "ALL HAIL THE PATCH!", "The meat disappears into its folds with a squelching crunch.", "The giant cabbage rustles, unimpressed by your offering."});
